// Writes idtables.go: the non-ASCII identifier characters of vega-expression's
// parser (its RegexNonAsciiIdentifierStart and RegexNonAsciiIdentifierPart),
// as ranges of UTF-16 code units. TestIdentifierCharacters checks the tables
// against what upstream's parser accepts.
//
//   NODE_PATH=testdata/oracle-node/node_modules node internal/expr/testdata/gen_idtables.mjs > internal/expr/idtables.go && gofmt -w internal/expr/idtables.go
import path from 'node:path';
import fs from 'node:fs';
const src = fs.readFileSync(path.resolve(process.env.NODE_PATH, 'vega-expression/src/parser.js'), 'utf8');
const ranges = name => {
  const m = src.match(new RegExp(name + " = new RegExp\\('\\[([^\\]]*)\\]'\\)"));
  if (!m) throw new Error('no ' + name);
  const re = new RegExp('[' + m[1].replace(/\\\\/g, '\\') + ']');
  const out = [];
  for (let c = 0x80; c <= 0xFFFF; c++) {
    if (!re.test(String.fromCharCode(c))) continue;
    const last = out[out.length - 1];
    if (last && last[1] === c - 1) last[1] = c; else out.push([c, c]);
  }
  return out;
};
const hex = c => '0x' + c.toString(16).toUpperCase().padStart(4, '0');
const table = (name, rs) => `var ${name} = []uint16{\n` + rs.map(([a, b]) => `\t${hex(a)}, ${hex(b)},\n`).join('') + '}\n';
process.stdout.write(`// Code generated by testdata/gen_idtables.mjs from vega-expression's parser; DO NOT EDIT.

package expr

// idStartRanges and idPartRanges are the non-ASCII UTF-16 code units
// vega-expression takes as the first and as a later character of an
// identifier (its RegexNonAsciiIdentifierStart and RegexNonAsciiIdentifierPart,
// fixed tables of an old Unicode version), as inclusive [lo, hi] pairs.

${table('idStartRanges', ranges('RegexNonAsciiIdentifierStart'))}
${table('idPartRanges', ranges('RegexNonAsciiIdentifierPart'))}`);
